function trimLines(text){ return String(text).split('\n').map(function(l){return l.trim();}).join('\n'); }
function removeBlankLines(text){ return String(text).split('\n').filter(function(l){return l.trim().length>0;}).join('\n'); }
function collapseSpaces(text){ return String(text).replace(/[\t ]+/g, ' ').trim(); }
function uniqueLines(text, keepOrder){
  var seen={}, out=[];
  String(text).split('\n').forEach(function(l){
    var k=l.trim();
    if(!seen[k]){ seen[k]=1; out.push(l); }
  });
  return out.join('\n');
}
var EXPORTS = { trimLines:trimLines, removeBlankLines:removeBlankLines, collapseSpaces:collapseSpaces, uniqueLines:uniqueLines };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WhitespaceForgePure = EXPORTS; }
